import fs from 'node:fs';
import assert from 'node:assert/strict';
const report = JSON.parse(fs.readFileSync('docs/data/bkl042-f5-real-evidence-evaluation.json', 'utf8'));
assert.equal(report.evaluationType, 'BKL042_F5_REAL_EVIDENCE_EVALUATION');
assert.equal(report.evaluationState, 'F5_TECHNICAL_GATE_EVALUATED');
assert.equal(report.outcomes.technical.state, 'ACCEPTED_READ_ONLY_WITH_LIMITATIONS');
assert.equal(report.outcomes.scientific.state, 'NOT_EVALUABLE_CURRENT_EVIDENCE');
assert.equal(report.outcomes.production.state, 'NOT_READY_FOR_PRODUCTION');
assert.equal(report.outcomes.aiModelImplemented, false);
assert.equal(report.authority.acceptanceAuthority, 'HUMAN_ONLY');
assert.equal(report.authority.actionAuthority, 'NONE');
assert.equal(report.authority.commandAuthority, 'NONE');
assert.equal(report.authority.executionAuthority, 'NONE');
assert.equal(report.authority.safetyAuthority, 'NONE');
assert.equal(report.authority.automaticAcceptanceAuthorized, false);
assert.equal(report.authority.pixInsightApplyAuthorized, false);
assert.ok(report.technicalGates.some(gate => gate.gateId === 'F5-T05-REAL-EVIDENCE' && gate.state === 'NOT_EVALUABLE'));
assert.ok(report.limitations.some(item => item.includes('Formal ARB')));
console.log('BKL-042-F5 evaluation PASS: bounded read-only technical closure with fail-closed real-evidence limitation');
